/// The options of [`SlackUser::wait_for_modal`].
pub struct SlackUserWaitForModal {
    ctx: Ctx,
    me: Value,
    seen: Seen,
    options: Map<String, Value>,
}

impl SlackUserWaitForModal {
    /// `title`.
    pub fn title(mut self, value: impl IntoArg) -> Self {
        self.options.insert("title".into(), value.into_arg());
        self
    }
    /// `timeout`.
    pub fn timeout(mut self, value: impl IntoArg) -> Self {
        self.options.insert("timeout".into(), value.into_arg());
        self
    }
    /// Wait.
    pub async fn send(self) -> Result<SlackModal> {
        let Self {
            ctx,
            me,
            seen,
            options,
        } = self;
        let _ = &seen;
        let filters: Map<String, Value> = options
            .iter()
            .filter(|(name, _)| [].contains(&name.as_str()))
            .map(|(name, value)| (name.clone(), value.clone()))
            .collect();
        let timeout = options
            .get("timeout")
            .cloned()
            .unwrap_or_else(|| Value::from(DEFAULT_TIMEOUT));
        let text = options.get("title").cloned().unwrap_or(Value::Null);
        check_text(&text)?;
        let item = wait_for_next(
            &seen.positions,
            "waitForModal",
            || run_slack_user_modals(&ctx, &me, vec![], filters.clone()),
            |item: &Value| {
                text_matches(
                    item.get("title").and_then(Value::as_str).unwrap_or(""),
                    &text,
                ) && item.get("open") == Some(&Value::from(true))
            },
            None,
            "an open modal from the agent",
            &timeout,
        )
        .await?;
        SlackModal::wrap(&ctx, item)
    }
}

impl IntoFuture for SlackUserWaitForModal {
    type Output = Result<SlackModal>;
    type IntoFuture = BoxFuture<'static, Result<SlackModal>>;
    fn into_future(self) -> Self::IntoFuture {
        Box::pin(self.send())
    }
}

