/// The options of [`SlackDelivery::settled`].
pub struct SlackDeliverySettled {
    ctx: Ctx,
    me: Value,
    seen: Seen,
    options: Map<String, Value>,
}

impl SlackDeliverySettled {
    /// `timeout`.
    pub fn timeout(mut self, value: impl IntoArg) -> Self {
        self.options.insert("timeout".into(), value.into_arg());
        self
    }
    /// Wait.
    pub async fn send(self) -> Result<SlackDelivery> {
        let Self {
            ctx,
            me,
            seen,
            options,
        } = self;
        let _ = &seen;
        let filters: Map<String, Value> = options
            .iter()
            .filter(|(name, _)| [].contains(&name.as_str()))
            .map(|(name, value)| (name.clone(), value.clone()))
            .collect();
        let timeout = options
            .get("timeout")
            .cloned()
            .unwrap_or_else(|| Value::from(DEFAULT_TIMEOUT));
        let value = wait_for("the delivery to settle", &timeout, || {
            let read = run_slack_delivery_refresh(&ctx, &me, vec![], filters.clone());
            async move {
                let value = read.await?;
                Ok((!["pending"]
                    .contains(&value.get("status").and_then(Value::as_str).unwrap_or("")))
                .then_some(value))
            }
        })
        .await?;
        SlackDelivery::wrap(&ctx, value)
    }
}

impl IntoFuture for SlackDeliverySettled {
    type Output = Result<SlackDelivery>;
    type IntoFuture = BoxFuture<'static, Result<SlackDelivery>>;
    fn into_future(self) -> Self::IntoFuture {
        Box::pin(self.send())
    }
}

