/// The options of [`GitHubPullRequest::wait_for_comment`].
pub struct GitHubPullRequestWaitForComment {
    ctx: Ctx,
    me: Value,
    seen: Seen,
    options: Map<String, Value>,
}

impl GitHubPullRequestWaitForComment {
    /// `from`.
    pub fn from(mut self, value: impl IntoArg) -> Self {
        self.options.insert("from".into(), value.into_arg());
        self
    }
    /// `body`.
    pub fn body(mut self, value: impl IntoArg) -> Self {
        self.options.insert("body".into(), value.into_arg());
        self
    }
    /// `timeout`.
    pub fn timeout(mut self, value: impl IntoArg) -> Self {
        self.options.insert("timeout".into(), value.into_arg());
        self
    }
    /// Wait.
    pub async fn send(self) -> Result<GitHubComment> {
        let Self {
            ctx,
            me,
            seen,
            options,
        } = self;
        let _ = &seen;
        let filters: Map<String, Value> = options
            .iter()
            .filter(|(name, _)| [].contains(&name.as_str()))
            .map(|(name, value)| (name.clone(), value.clone()))
            .collect();
        let timeout = options
            .get("timeout")
            .cloned()
            .unwrap_or_else(|| Value::from(DEFAULT_TIMEOUT));
        let from = options.get("from").cloned().unwrap_or(Value::Null);
        let text = options.get("body").cloned().unwrap_or(Value::Null);
        check_text(&text)?;
        let item = wait_for_next(
            &seen.positions,
            "waitForComment",
            || run_git_hub_issue_comments(&ctx, &me, vec![], filters.clone()),
            |item: &Value| {
                from_matches(item.get("author").unwrap_or(&Value::Null), &from)
                    && text_matches(
                        item.get("body").and_then(Value::as_str).unwrap_or(""),
                        &text,
                    )
            },
            None,
            &match &from {
                Value::Null => "a comment".to_owned(),
                Value::String(name) => format!("{} from {}", "a comment", name),
                other => format!(
                    "{} from {}",
                    "a comment",
                    other.get("name").and_then(Value::as_str).unwrap_or("")
                ),
            },
            &timeout,
        )
        .await?;
        GitHubComment::wrap(&ctx, item)
    }
}

impl IntoFuture for GitHubPullRequestWaitForComment {
    type Output = Result<GitHubComment>;
    type IntoFuture = BoxFuture<'static, Result<GitHubComment>>;
    fn into_future(self) -> Self::IntoFuture {
        Box::pin(self.send())
    }
}

