/// The resource a handle's field holds, when it holds one (`SlackMessage.thread` → `SlackThread`).
pub fn field_resource(resource: &str, field: &str) -> Option<&'static str> {
    match (resource, field) {
        ("EchoFixture", "app") => Some("EchoApp"),
        ("SlackFixture", "app") => Some("SlackApp"),
        ("SlackMessage", "conversation") => Some("SlackConversation"),
        ("SlackMessage", "visibleTo") => Some("SlackUser"),
        ("SlackMessage", "thread") => Some("SlackThread"),
        ("SlackMessage", "delivery") => Some("SlackDelivery"),
        ("SlackMessage", "stream") => Some("SlackStream"),
        ("SlackThread", "conversation") => Some("SlackConversation"),
        ("SlackModal", "user") => Some("SlackUser"),
        ("GitHubFixture", "app") => Some("GitHubApp"),
        ("GitHubIssue", "repo") => Some("GitHubRepo"),
        ("GitHubComment", "issue") => Some("GitHubIssue"),
        ("GitHubComment", "delivery") => Some("GitHubDelivery"),
        ("GitHubReviewComment", "pr") => Some("GitHubPullRequest"),
        ("GitHubReviewComment", "delivery") => Some("GitHubDelivery"),
        ("LinearFixture", "app") => Some("LinearApp"),
        ("LinearIssue", "team") => Some("LinearTeam"),
        ("LinearAgentSession", "issue") => Some("LinearIssue"),
        ("LinearAgentSession", "app") => Some("LinearApp"),
        ("LinearAgentSession", "startedBy") => Some("LinearUser"),
        ("LinearAgentSession", "delivery") => Some("LinearDelivery"),
        ("LinearComment", "issue") => Some("LinearIssue"),
        ("LinearComment", "session") => Some("LinearAgentSession"),
        ("LinearComment", "delivery") => Some("LinearDelivery"),
        ("LinearAgentActivity", "session") => Some("LinearAgentSession"),
        ("NotionFixture", "app") => Some("NotionIntegration"),
        ("NotionComment", "discussion") => Some("NotionDiscussion"),
        ("NotionComment", "delivery") => Some("NotionDelivery"),
        ("NotionDiscussion", "page") => Some("NotionPage"),
        ("ResendFixture", "app") => Some("ResendApp"),
        ("ResendEmail", "thread") => Some("ResendThread"),
        ("ResendEmail", "delivery") => Some("ResendDelivery"),
        ("GoogleFixture", "app") => Some("GoogleApp"),
        ("GoogleEmail", "thread") => Some("GoogleThread"),
        ("GoogleEmail", "delivery") => Some("GoogleDelivery"),
        ("GitHubPullRequest", "repo") => Some("GitHubRepo"),
        _ => None,
    }
}

/// Attach to a running channelstack server, or start one (`Mode`), and answer the client.
pub async fn connect(mode: Mode) -> Result<Channelstack> {
    connect_with(mode, None, None).await
}

/// `connect`, to a server at this URL, with this token: otherwise they come from the environment or `server.json`.
pub async fn connect_with(
    mode: Mode,
    server: Option<&str>,
    token: Option<&str>,
) -> Result<Channelstack> {
    let mut connection = launch(mode, server, token).await?;
    let started = std::sync::Arc::new(std::sync::Mutex::new(connection.started.take()));
    let transport = std::sync::Arc::new(crate::runtime::transport::Transport::new(
        &connection.url,
        &connection.token,
        BASE_PATH,
    )?);
    let ctx = Ctx {
        transport,
        session: None,
        started,
    };
    let status = match ctx.transport.request("GET", "/status", None, None).await {
        Ok(status) => status,
        Err(error) => {
            Channelstack::from_wire(&ctx, Value::Null).close().await;
            return Err(error);
        }
    };
    let version = status
        .get("version")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_owned();
    if version.split('.').next() != VERSION.split('.').next() {
        Channelstack::from_wire(&ctx, Value::Null).close().await;
        return Err(Error::Launch(format!(
            "The channelstack server is version {version}, but this SDK was generated for {VERSION}"
        )));
    }
    Ok(Channelstack::from_wire(&ctx, Value::Null))
}
